"""Authored exam questions; descriptions and distractors share one answer dimension."""
PRESETS={}
def add(title,stem,choices,notes,extension='先确定题目问的是对象、条件还是作用，再逐项判断；把相近概念放在一起对照复习。'):
 assert len(choices)==len(notes)==4
 PRESETS[title]=(stem,choices,notes,extension)
def concept(title,stem,rows,extension='先看情境中的关键条件，再比较相近概念的适用范围。'):
 add(title,stem,[r[0] for r in rows],[r[1] for r in rows],extension)
concept('机会成本','某企业可用同一组设备生产甲、乙、丙三种产品，预计净收益分别为10万元、8万元、6万元。三种方案互斥，企业选择生产甲产品，其机会成本是（ ）。',[
 ('8万元','正确。放弃的可行方案中，乙方案收益最高，为8万元。机会成本取最佳备选收益。'),('6万元','错误。丙方案也是被放弃的方案，但不是收益最高的备选。'),('14万元','错误。8万元与6万元不能相加，因为乙、丙方案也互斥，不能同时实现。'),('10万元','错误。这是所选甲方案的收益，不是放弃的最佳备选收益。')], '机会成本是放弃的最佳备选收益；沉没成本是已经发生且无法收回的支出。比较方案时，避免把所有备选收益相加。')
concept('恩格尔系数','某家庭全年消费支出为10万元，其中食品支出为3万元。该家庭的恩格尔系数是（ ）。',[
 ('30%','正确。食品支出÷消费支出×100%，即3÷10×100%=30%。'),('70%','错误。70%对应非食品消费支出的比重。'),('3%','错误。3÷10应换算为30%，不是3%。'),('无法计算，必须先知道家庭总收入','错误。分母是消费支出，不是收入；题目已经提供所需数据。')], '先认分子“食品支出”和分母“消费支出”。储蓄不是当期消费支出，不能把家庭总收入直接作分母。')
concept('马克思主义哲学的创立','马克思主义哲学实现哲学史上伟大变革的关键在于确立了（ ）。',[
 ('科学的实践观','正确。实践观点把唯物论、辩证法、认识论与历史观连接起来。'),('把精神看作世界本原的观点','错误。这属于唯心主义方向，与马克思主义哲学的唯物主义立场不同。'),('认为事物永远静止的观点','错误。这否认运动变化，与辩证法不符。'),('仅凭抽象思辨解释社会历史的观点','错误。马克思主义哲学强调现实的社会实践，不能归结为抽象思辨。')])
concept('辩证否定的实质','关于辩证否定的实质“扬弃”，下列理解正确的是（ ）。',[
 ('既克服旧事物中消极的方面，又保留其中积极的因素','正确。扬弃包含克服和保留，是联系与发展的环节。'),('把旧事物全部抛弃，不保留任何因素','错误。这把否定理解为全盘抛弃，割裂了新旧事物的联系。'),('原封不动地保留旧事物','错误。只有保留而没有克服，不构成辩证否定。'),('依靠外力任意消灭旧事物','错误。辩证否定强调事物自身矛盾运动所引起的否定，不是外力的任意破坏。')])
concept('质变','水在一定条件下受热，温度逐渐升高，达到沸点后由液态转变为气态。这说明（ ）。',[
 ('量变达到一定程度会引起质变','正确。温度积累到一定条件，出现物态变化，体现量变向质变转化。'),('任何微小量变都会立即引起质变','错误。量变引起质变需要达到一定程度，不能省略条件。'),('量变与质变毫无联系','错误。量变是质变的必要准备，质变是量变的必然结果。'),('质变发生后不可能再有量变','错误。质变为新的量变开辟道路，发展并不会就此终止。')])
concept('实践','某项农业技术在实验室取得初步结果后，又经过多地田间试验，才确定其适用条件。这主要体现实践是（ ）。',[
 ('检验认识真理性的唯一标准','正确。通过实际试验检验技术认识是否符合客观情况。'),('认识的唯一获得途径','错误。获取认识有直接和间接途径，书本学习也能获得认识。'),('不受客观条件限制的活动','错误。实践受客观条件制约，题目特别强调不同地点和适用条件。'),('认识一旦形成便不再需要的活动','错误。认识要接受实践检验，并随实践发展而深化。')])
concept('人民币上的五种文字分别','人民币票面使用的五种文字包括（ ）。',[
 ('汉字、蒙古文、藏文、维吾尔文、壮文','正确。这是题目所问的五种票面文字。'),('汉字、蒙古文、藏文、维吾尔文、朝鲜文','错误。把壮文替换成了朝鲜文。'),('汉字、蒙古文、藏文、壮文、满文','错误。漏掉维吾尔文，并加入了满文。'),('汉字、藏文、维吾尔文、壮文、英文','错误。漏掉蒙古文，并加入了英文。')])
concept('最高人民检察院对全国人大及其常委会','关于最高人民检察院的地位和职责，下列说法正确的是（ ）。',[
 ('对全国人民代表大会及其常务委员会负责，领导地方各级和专门人民检察院的工作','正确。这里同时考查最高检的负责对象与对下级检察院的领导关系。'),('对国务院负责，领导地方各级人民法院的工作','错误。负责对象与工作对象均混淆，检察院与法院是不同国家机关。'),('对最高人民法院负责，领导地方各级人民检察院的工作','错误。最高检不对最高法负责，不能把两个最高司法机关当成上下级。'),('对全国人大负责，只监督而不领导地方各级人民检察院的工作','错误。最高检与下级检察院是领导关系，不能套用法院之间的监督关系。')])
concept('唐宋八大家','下列人物中，均属于唐宋八大家的是（ ）。',[
 ('韩愈、柳宗元、欧阳修、王安石','正确。韩愈、柳宗元为唐代两家；欧阳修、王安石属于宋代六家。'),('李白、杜甫、白居易、韩愈','错误。李白、杜甫、白居易不属于唐宋八大家，不能把著名诗人直接列入。'),('苏轼、苏洵、苏辙、辛弃疾','错误。三苏属于八大家，辛弃疾不在这一名单内。'),('欧阳修、曾巩、王安石、陆游','错误。前三者属于八大家，陆游不在名单内。')], '八大家指唐宋散文家：韩、柳、欧、王、三苏、曾。名单分类与诗词名家分类不同。')
for title,stem,correct,others in [
 ('升华','樟脑丸放置一段时间后变小，且未出现液体。其主要物态变化是（ ）。','升华',['凝华','汽化','液化']),
 ('凝华','冬季玻璃上出现冰花，水蒸气直接形成冰晶。其物态变化是（ ）。','凝华',['凝固','液化','升华']),
 ('液化','冬天从室外进入温暖的室内，眼镜表面出现小水珠。水珠形成涉及的物态变化是（ ）。','液化',['汽化','凝华','凝固']),
 ('汽化','把湿衣服晾在通风处，衣服逐渐变干。水发生的主要物态变化是（ ）。','汽化',['液化','升华','熔化'])]:
 descriptions={'升华':'固态直接变为气态，需要吸热','凝华':'气态直接变为固态，会放热','液化':'气态变为液态，会放热','汽化':'液态变为气态，需要吸热','凝固':'液态变为固态，会放热','熔化':'固态变为液态，需要吸热'}
 add(title,stem,[correct]+others,[('正确。' if i==0 else '错误。')+descriptions[x]+'，'+('符合题目所述变化。' if i==0 else '与题目中的初始和最终物态不同。') for i,x in enumerate([correct]+others)],'先判断初始和最终物态，再判断吸热或放热。蒸发和沸腾都属于汽化。')
ages={'而立':30,'不惑':40,'知天命':50,'耳顺':60,'古稀':70,'弱冠':20,'及笄':15}
for title,age in ages.items():
 vals=[age]+[x for x in (15,20,30,40,50,60,70) if x!=age][:3]
 add(title,f'传统年龄称谓中，“{title}”通常指（ ）。',[f'{x}岁' for x in vals], [('正确。' if i==0 else '错误。')+f'{x}岁对应“{next(t for t,a in ages.items() if a==x)}”，'+('符合题意。' if i==0 else f'不是“{title}”。') for i,x in enumerate(vals)],'年龄称谓按15、20、30、40、50、60、70岁排列，分别记及笄、弱冠、而立、不惑、知天命、耳顺、古稀。及笄传统上用于女子，弱冠用于男子。')
times=['子时','丑时','寅时','卯时','辰时','巳时','午时','未时','申时','酉时','戌时','亥时']
labels=['23时至次日1时']+[f'{2*i-1}时至{2*i+1}时' for i in range(1,12)]
for i,title in enumerate(times):
 indexes=[i,(i+1)%12,(i+3)%12,(i+6)%12]
 add(title,f'传统十二时辰中，“{title}”大致对应现代时间的（ ）。',[labels[j] for j in indexes],[('正确。' if j==i else '错误。')+f'{labels[j]}对应{times[j]}，'+('符合题意。' if j==i else f'不是{title}。') for j in indexes],'一时辰约两小时，从子时23时至次日1时开始，每次向后推两小时。子时跨越午夜，注意日期边界。')
months=['孟春','仲春','季春','孟夏','仲夏','季夏','孟秋','仲秋','季秋','孟冬','仲冬','季冬']
for i,title in enumerate(months):
 indexes=[i,(i+1)%12,(i+3)%12,(i+6)%12]
 add(title,f'传统月份称谓中的“{title}”指农历（ ）。',[f'{j+1}月' for j in indexes],[('正确。' if j==i else '错误。')+f'农历{j+1}月称{months[j]}，'+('符合题意。' if j==i else f'不是{title}。') for j in indexes],'春夏秋冬分别对应农历1—3、4—6、7—9、10—12月；每季依次称孟、仲、季。这是月份称谓，不是公历月份或节气日期。')
concept('新旧事物区分的标志','判断某事物是新事物还是旧事物，应主要看它（ ）。',[
 ('是否符合事物发展的必然趋势','正确。判断标准在于本质和发展趋势。'),('出现的时间是否较晚','错误。时间晚不一定意味着本质上先进。'),('名称是否新颖','错误。新名称不能改变旧事物的本质。'),('形式是否与过去不同','错误。形式变化不能单独作为新旧事物的根本标准。')])
concept('近视的成像与矫正','近视眼看远处物体时，像通常落在视网膜前。常用的矫正镜片是（ ）。',[
 ('凹透镜','正确。凹透镜使入射光适当发散，使像向后移到视网膜上。'),('凸透镜','错误。凸透镜会聚光线，常用于矫正远视，不能与近视混用。'),('平面镜','错误。平面镜主要改变光的传播方向，不提供所需的发散作用。'),('普通平光玻璃','错误。没有所需的光焦度，不能按题目原理矫正近视。')])
concept('远视的成像与矫正','远视眼看近处物体时，像通常落在视网膜后。常用的矫正镜片是（ ）。',[
 ('凸透镜','正确。凸透镜会聚光线，使像向前移到视网膜上。'),('凹透镜','错误。凹透镜发散光线，通常用于矫正近视。'),('平面镜','错误。平面镜不能提供矫正远视需要的会聚作用。'),('普通平光玻璃','错误。平光玻璃没有所需的光焦度。')])
concept('声音传播的介质','宇航员在太空中不能直接听见远处爆炸的声音，却可以看到闪光，主要原因是（ ）。',[
 ('声音传播需要介质，光可以在真空中传播','正确。声波是机械波，光是电磁波，两者对传播介质的要求不同。'),('声音和光都不能在真空中传播','错误。光能够在真空传播。'),('声音可以在真空传播，光不能','错误。把声波和电磁波的性质颠倒了。'),('声音只能在空气中传播','错误。声音也可在液体和固体中传播，关键是存在介质。')])
concept('科学发展观核心立场','科学发展观的核心立场是（ ）。',[
 ('以人为本','正确。这回答发展的核心立场问题。'),('发展','错误。这是科学发展观的第一要义。'),('全面协调可持续','错误。这是科学发展观的基本要求。'),('统筹兼顾','错误。这是科学发展观的根本方法。')])
